  test("terms by version scenario 1", { tag: '@functionality' }, async ({ browser }) => {
-- The terms (business days) a claim's due-by was fixed with, so it can be worked out again from its
-- date when a holiday is added. Filled for the claims kept by the next migration.
ALTER TABLE public.claim ADD COLUMN due_terms INT;
ALTER TABLE asof.claim ADD COLUMN due_terms INT;
ALTER TABLE asof_hist.claim ADD COLUMN due_terms INT;
-- The history trigger keeps the column list it was created with: create it again to see the new one.
DROP TRIGGER public.claim_history;
CREATE TRIGGER claim_history AFTER INSERT, UPDATE, DELETE ON public.claim FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';
-- A person's own terms can be dated: each is in force from its from-date, kept as `from:terms` pairs
-- (yyyy-mm-dd, terms blank for none) sorted by from-date and separated by commas (null: none).
-- `person.terms` stays the terms from the beginning of time. The terms in force on a date are the
-- ones with the latest from-date on or before it, else `person.terms`.
ALTER TABLE public.person ADD COLUMN dated_terms VARCHAR(4000);
ALTER TABLE asof.person ADD COLUMN dated_terms VARCHAR(4000);
ALTER TABLE asof_hist.person ADD COLUMN dated_terms VARCHAR(4000);
-- The history trigger keeps the column list it was created with: create it again to see the new one.
DROP TRIGGER public.person_history;
CREATE TRIGGER person_history AFTER INSERT, UPDATE, DELETE ON public.person FOR EACH ROW CALL 'net.officefloor.hq.app.sheet.History';
-- A claim's due, fixed when it is settled: amount times its person's grade's rate then, divided
-- by 100, rounded half up to two decimals. Null while the claim is not settled, or when it was
-- settled with no rate (n/a): such a claim's due stays live, at the current rate.
ALTER TABLE claim ADD COLUMN due DECIMAL(14,2);
